import random
def experiment(inputs):
    seeds = inputs.get('seeds', range(10))
    variances = []
    for seed in seeds:
        random.seed(seed)
        data = [random.gauss(0.5, 1.0) for _ in range(100)]
        mean = sum(data) / len(data)
        var = sum((x - mean) ** 2 for x in data) / len(data)
        variances.append(var)
    return {'measurements': {'preference_variance': variances}}

